import bisect
class Solution:
    def searchRange(self, a: list[int], target: int) -> list[int]:
        l = bisect.bisect_left(a, target)
        r = bisect.bisect_right(a, target)
        if l == r:
            return [-1, -1]
        return [l, r - 1]

