class Solution:
    def shipWithinDays(self, w: list[int], days: int) -> int:
        def ok(cap):
            d, cur = 1, 0
            for x in w:
                if cur + x > cap:
                    d += 1
                    cur = 0
                cur += x
            return d <= days
        lo, hi = max(w), sum(w)
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution {
    int parts(vector<int>& a, long long cap){
        int p = 1; long long cur = 0;
        for (int x : a){ if (cur + x > cap){ p++; cur = 0; } cur += x; }
        return p;
    }
public:
    int splitArray(vector<int>& a, int k) {
        long long lo = *max_element(a.begin(), a.end());
        long long hi = accumulate(a.begin(), a.end(), 0LL);
        while (lo < hi){ long long mid = (lo + hi) / 2; if (parts(a, mid) <= k) hi = mid; else lo = mid + 1; }
        return (int)lo;
    }
};

class Solution:
    def splitArray(self, nums: list[int], k: int) -> int:
        def parts(cap):
            p, cur = 1, 0
            for x in nums:
                if cur + x > cap:
                    p += 1
                    cur = 0
                cur += x
            return p
        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if parts(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution {
public:
    int findPeakElement(vector<int>& a) {
        int lo = 0, hi = a.size() - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] < a[mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
};

class Solution:
    def findPeakElement(self, a: list[int]) -> int:
        lo, hi = 0, len(a) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < a[mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        return lo
